@testable import Business
import Domain
import Foundation
@testable import Presentation
import Testing
import TestMocks

@MainActor
private func makeBroadsheetAppState() -> BroadsheetAppState {
    let storage = MockStorageEngine()
    let capture = MockAudioCaptureEngine()
    let pipelineCoordinator = PipelineCoordinator(
        cleanupTranscribe: CleanupTranscriptionUseCase(
            transcription: MockTranscriptionEngine(),
            sampleLoader: MockAudioSampleLoader(),
            reader: storage, writer: storage
        ),
        diarizeMeeting: DiarizeMeetingUseCase(
            diarization: MockDiarizationEngine(),
            sampleLoader: MockAudioSampleLoader(),
            reader: storage, writer: storage
        ),
        summarizeMeeting: SummarizeMeetingUseCase(summarization: MockSummarizationEngine())
    )

    let menuBarVM = MenuBarViewModel(dependencies: .init(
        startRecording: StartRecordingUseCase(audioCapture: capture, storage: storage),
        stopAndTranscribe: StopAndTranscribeUseCase(
            audioCapture: capture,
            transcription: MockTranscriptionEngine(),
            storage: storage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("openai_whisper-tiny")
        ),
        pipelineCoordinator: pipelineCoordinator,
        deleteRecording: DeleteRecordingUseCase(storage: storage),
        searchRecordings: SearchRecordingsUseCase(storage: storage),
        autoCleanup: AutoCleanupUseCase(reader: storage, writer: storage),
        exportAudio: ExportAudioUseCase(storage: storage, exportEngine: MockAudioExportEngine())
    ))
    let libraryVM = MeetingLibraryViewModel(storage: storage)
    let globalAppState = AppState(
        recording: menuBarVM.recordingStateVM,
        library: libraryVM,
        initialConfig: .default
    )
    menuBarVM.bindAppState(globalAppState)

    let detailVM = MeetingDetailViewModel(reader: storage, writer: storage)
    let commitmentsVM = CommitmentsViewModel(useCase: TrackCommitmentsUseCase(store: MockCommitmentStore()))
    return BroadsheetAppState(
        appState: globalAppState,
        menuBarVM: menuBarVM,
        libraryVM: libraryVM,
        detailVM: detailVM,
        commitmentsVM: commitmentsVM
    )
}

